const ads = $input.all().map(i => i.json);
let html = '<h2>Weekly Competitor Ads Intelligence Digest</h2><ul>';
for (const ad of ads) {
  html += `<li><b>${ad.advertiserName || ad.target}</b> (${ad.format}): ${ad.headline || 'No headline'} — <a href="${ad.adUrl}">View Ad</a></li>`;
}
html += '</ul>';
return [{ json: { html, total: ads.length } }];
